record.field:
# Read auth credentials from remote.connection_params JSON
remote = self.remote_id
cfg = {}
try:
    cfg = json.loads(remote.connection_params or '{}')
except Exception:
    cfg = {}

username = (cfg.get('username') or '').strip()
password = (cfg.get('password') or '').strip()

if not username or not password:
    raise Exception("Missing Spherag credentials: set username/password in connection_params.")

# Login endpoint is /Authentication/Login
url = (base_url or '').rstrip('/') + '/Authentication/Login'

payload = {
    'username': username,
    'password': password
}

resp = request_retry('POST', url, json=payload, timeout=timeout)

if resp.status_code >= 400:
    raise Exception("Spherag login failed: %s %s" % (resp.status_code, resp.text))

try:
    j = resp.json()
    if not isinstance(j, dict):
        raise Exception("Invalid JSON response format from login endpoint")
except Exception as json_err:
    raise Exception("Failed to parse login response: %s" % str(json_err))

access_token_obj = j.get('accessToken')
if not access_token_obj or not isinstance(access_token_obj, dict):
    raise Exception("Login response missing 'accessToken' object")

access_token = access_token_obj.get('token') or ''

if not access_token or not isinstance(access_token, (str, unicode)):
    raise Exception("Login OK but no valid 'accessToken.token' string in response")

# Store token in bag (not persisted between executions)
bag['access_token'] = access_token
bag['token_expiration'] = access_token_obj.get('expiration', '')

Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
today_str = fields.Date.today()

condition = [
    ('remotecontrol_params', '!=', False),
    ('device_id.remotecontrol_id', '=', Remote.id)
]

if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))

sensors = Sensor.search(condition)

# Optimize: build map of sensor_id -> most recent reading (single query)
last_readings_map = {}
if sensors:
    sensor_ids = [s.id for s in sensors]
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for row in cr.fetchall():
        last_readings_map[row[0]] = row[1]

# Build plan for each sensor
plan = []
for sensor in sensors:
    device = sensor.device_id

    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}

    try:
        device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
    except Exception:
        device_cfg = {}

# Get configuration with validation
    system_id = device_cfg.get('system_id')
    imei = device_cfg.get('imei')
    atlas_element_id = sensor_cfg.get('atlas_element_id')
    chart_type = sensor_cfg.get('chart_type')
    data_type = sensor_cfg.get('data_type', 'sensor_data')  # Default to sensor_data
    data_array_index = sensor_cfg.get('data_array_index', 0)  # Default to first array
    value_index = sensor_cfg.get('value_index', 0)  # Default to first position
    start_cfg = sensor_cfg.get('start_date') or device_cfg.get('start_date')

    # Validate all required fields are present and not None/empty
    if not system_id or not imei or not atlas_element_id or not chart_type:
        # Log warning about missing configuration
        continue

    # Determine initial date
    last_reading_time = last_readings_map.get(sensor.id)
    if last_reading_time:
        try:
            initial_date = fields.Date.to_string(
                fields.Datetime.from_string(last_reading_time)
            )
        except Exception:
            initial_date = str(last_reading_time)[:10]
    elif start_cfg:
        initial_date = start_cfg[:10]
    else:
        year_str = today_str[:4]
        initial_date = '%s-01-01' % year_str

    if isinstance(initial_date, unicode):
        initial_date = initial_date.encode('utf-8')

    plan.append({
        'sensor_id': sensor.id,
        'device_id': device.id,
        'system_id': system_id,
        'imei': imei,
        'atlas_element_id': atlas_element_id,
        'chart_type': chart_type,
        'data_type': data_type,
        'data_array_index': data_array_index,
        'value_index': value_index,
        'initial_date': initial_date
    })

bag['sensors_plan'] = plan

Remote = self.remote_id access_token = bag.get('access_token')
if not access_token: raise Exception("Missing Spherag access_token in bag")
# Get API core URL and systemId from connection params cfg = {} try: cfg = json.loads(Remote.connection_params or '{}') except Exception: cfg = {}
api_core_url = (cfg.get('api_core_url') or 'https://apicore.spherag.com').rstrip('/') system_id = cfg.get('system_id') or bag.get('system_id')
if not system_id: raise Exception("Missing system_id in connection_params. Please add 'system_id': 1401 to the remotecontrol connection_params JSON field.")
headers = { 'Authorization': 'Bearer %s' % access_token, 'Accept': 'application/json' }
# 1. Get Atlas devices with pagination api_calls = [] atlas_devices = []
# Pagination: fetch all pages page = 1 limit = 100 has_next_page = True
while has_next_page: url_atlas = '%s/systems/%s/Atlas?Init=%s&Limit=%s' % (api_core_url, system_id, page, limit) resp_atlas = request_retry('GET', url_atlas, headers=headers, timeout=timeout)
if resp_atlas.status_code >= 400: raise Exception("Error fetching Atlas devices from URL %s: HTTP %s - %s" % (url_atlas, resp_atlas.status_code, resp_atlas.text))
resp_data = resp_atlas.json() or {}
# API returns paginated response with 'items' array items = resp_data.get('items') or [] atlas_devices.extend(items)
# Store API call info api_calls.append({ 'url': url_atlas, 'method': 'GET', 'status': resp_atlas.status_code, 'page': page, 'items_in_page': len(items), 'total_count': resp_data.get('totalCount', 0), 'total_pages': resp_data.get('totalPages', 0) })
# Check if there are more pages has_next_page = resp_data.get('hasNextPage', False) page += 1
# Safety limit to avoid infinite loops if page > 50: break
# 2. For each Atlas, get AtlasElements (sensors/connectors) devices_list = [] total_elements = 0
for atlas in atlas_devices: # Validate atlas is a dict if not isinstance(atlas, dict): continue
imei = atlas.get('imei') # Validate IMEI is not None or empty if not imei or str(imei).strip() == '': continue
device_entry = { 'id': atlas.get('id'), 'imei': str(imei).strip(), 'name': atlas.get('name') or str(imei), 'status': atlas.get('status'), 'batteryPercentage': atlas.get('batteryPercentage'), 'signalPercentage': atlas.get('signalPercentage'), 'elements': [], 'elements_url': '', 'elements_status': None, 'elements_error': None }
# Get AtlasElements: /systems/{systemId}/Atlas/{imei}/AtlasElements url_elements = '%s/systems/%s/Atlas/%s/AtlasElements' % (api_core_url, system_id, imei) device_entry['elements_url'] = url_elements try: resp_elements = request_retry('GET', url_elements, headers=headers, timeout=timeout) device_entry['elements_status'] = resp_elements.status_code if resp_elements.status_code < 400: elements = resp_elements.json() or []
for element in elements: if not isinstance(element, dict): continue
# API returns 'elementId' not 'id' element_id = element.get('elementId') or element.get('id') if element_id is None: continue
# Extract subsystem info if present subsystem = element.get('subsystem') or {}
element_entry = { 'id': element_id, 'name': element.get('name') or 'Element %s' % element_id, 'elementType': element.get('elementType'), 'subsystem_id': subsystem.get('id'), 'subsystem_name': subsystem.get('name'), 'subsystem_type': subsystem.get('subsystemType'), 'chart_types': [] }
# Get ChartTypes for this element url_charts = '%s/AtlasElement/Charts/%s' % (api_core_url, element_id) try: resp_charts = request_retry('GET', url_charts, headers=headers, timeout=timeout) if resp_charts.status_code < 400: charts = resp_charts.json() or [] for chart in charts: if isinstance(chart, dict): chart_id = chart.get('id') if chart_id is not None: element_entry['chart_types'].append({ 'id': chart_id, 'name': chart.get('name') or 'Chart %s' % chart_id }) except Exception as chart_err: element_entry['chart_types_error'] = str(chart_err)
device_entry['elements'].append(element_entry) total_elements += 1 else: device_entry['elements_error'] = 'HTTP %s: %s' % (resp_elements.status_code, (resp_elements.text or '')[:200])
except Exception as e: device_entry['elements_error'] = str(e)
devices_list.append(device_entry)
# Create summary data = { 'system_id': system_id, 'api_calls': api_calls, 'devices': devices_list, 'summary': { 'total_devices': len(devices_list), 'total_elements': total_elements, 'executed_at': fields.Datetime.now() } }
json_str = json.dumps(data, ensure_ascii=False, indent=2) encoded = base64.b64encode(json_str.encode('utf-8')) fname = 'spherag_devices_metrics_%s.json' % fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_')
att = env['ir.attachment'].create({ 'name': fname, 'datas_fname': fname, 'datas': encoded, 'mimetype': 'application/json', 'res_model': 'remotecontrol', 'res_id': Remote.id })
Remote.message_post( body=u'[Spherag] Devices=%s Elements=%s | Total Atlas: %s | API calls: %s' % ( len(devices_list), total_elements, len(atlas_devices), len(api_calls) ), attachment_ids=[att.id] )
bag['total_devices'] = len(devices_list) bag['total_elements'] = total_elements bag['attachment_id'] = att.id bag['attachment_name'] = fname
